package lucuma.odb.graphql
package feature

import cats.effect.IO
import cats.syntax.either.*
import io.circe.Json
import io.circe.literal.*
import lucuma.core.enums.CalibrationRole
import lucuma.core.model.Observation
import lucuma.odb.graphql.query.ExecutionTestSupportForFlamingos2

import java.time.LocalDateTime
import java.time.ZoneOffset

// The QA state override on a calibration generated by the calibrations
// service, which is otherwise read-only.
class observationQaCalibrations
  extends OdbSuite
  with ExecutionTestSupportForFlamingos2
  with TelluricCalibrationsTestSupport:

  val when = LocalDateTime.of(2024, 1, 1, 12, 0, 0).toInstant(ZoneOffset.UTC)

  def createTelluric: IO[Observation.Id] =
    for
      pid <- createProgramAs(pi)
      tid <- createTargetWithProfileAs(pi, pid)
      oid <- createFlamingos2LongSlitObservationAs(pi, pid, List(tid))
      _   <- runObscalcUpdate(pid, oid)
      _   <- recalculateCalibrations(pid, when, oid)
      tel <- calibrationObservationFor(oid, CalibrationRole.Telluric)
    yield tel.get

  def update(oid: Observation.Id, set: String): IO[Json] =
    query(staff, s"""
      mutation {
        updateObservations(input: {
          SET: { $set }
          WHERE: { id: { EQ: "$oid" } }
        }) {
          observations { id }
        }
      }
    """)

  def expectStored(oid: Observation.Id, subtitle: Option[String], over: Option[String]): IO[Unit] =
    expect(staff, s"""
      query {
        observation(observationId: "$oid") {
          calibrationRole
          subtitle
          qa { override }
        }
      }
    """, json"""
      {
        "observation": {
          "calibrationRole": "TELLURIC",
          "subtitle": $subtitle,
          "qa": { "override": $over }
        }
      }
    """.asRight)

  test("staff may set and clear the override of a generated telluric"):
    for
      tel <- createTelluric
      _   <- assertIO(update(tel, "qaStateOverride: FAIL"), json"""{ "updateObservations": { "observations": [ { "id": $tel } ] } }""")
      _   <- expectStored(tel, None, Some("FAIL"))
      _   <- update(tel, "qaStateOverride: null")
      _   <- expectStored(tel, None, None)
    yield ()

  test("an override combined with another field does not reach a generated telluric"):
    for
      tel <- createTelluric
      _   <- assertIO(update(tel, """qaStateOverride: FAIL, subtitle: "edited""""), json"""{ "updateObservations": { "observations": [] } }""")
      _   <- expectStored(tel, None, None)
    yield ()
